import os, json, datetime, base64from fastapi import FastAPI, Request, HTTPExceptionfrom google.cloud import storageimport requestsapp = FastAPI()BUCKET = os.getenv("KMS_GCS_BUCKET", "kms-central-knowingmind-app")SNAP_DIR = "KMS_CDH/snapshots"TARGET   = f"{SNAP_DIR}/kms_tasks_latest.json"LINE_WEBHOOK = os.getenv("SATISHIFT_WEBHOOK")  # optionalstorage_client = storage.Client()def _now_bkk_iso():    # Asia/Bangkok is UTC+7; naive approach for consistency    tz = datetime.timezone(datetime.timedelta(hours=7))    return datetime.datetime.now(tz).isoformat(timespec="seconds")def _load_latest():    bucket = storage_client.bucket(BUCKET)    blob = bucket.blob(TARGET)    if not blob.exists():        # initialize minimal structure        return {            "generated_at_local": _now_bkk_iso(),            "tasks": {"done": [], "next": [], "blockers": [], "notes": ""}        }    data = json.loads(blob.download_as_text(encoding="utf-8"))    if "tasks" not in data: data["tasks"] = {}    data["tasks"].setdefault("done", [])    data["tasks"].setdefault("next", [])    data["tasks"].setdefault("blockers", [])    data["tasks"].setdefault("notes", "")    return datadef _save_latest(data: dict):    bucket = storage_client.bucket(BUCKET)    # write latest    data["generated_at_local"] = _now_bkk_iso()    latest_blob = bucket.blob(TARGET)    latest_blob.upload_from_string(json.dumps(data, ensure_ascii=False, indent=2), content_type="application/json")    # write stamped copy    stamp = datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=7))).strftime("%Y%m%d")    stamped_blob = bucket.blob(f"{SNAP_DIR}/kms_tasks_{stamp}.json")    stamped_blob.upload_from_string(json.dumps(data, ensure_ascii=False, indent=2), content_type="application/json")def _notify_line(msg: str):    if not LINE_WEBHOOK:        return    try:        requests.post(LINE_WEBHOOK, json={"message": msg}, timeout=10)    except Exception:        pass@app.get("/healthz")def health():    return {"ok": True, "bucket": BUCKET}@app.post("/add_tasks")async def add_tasks(req: Request):    """    body JSON ตัวอย่าง:    { "tasks": ["ออกแบบ ARCHITECTURE_KMA_2025-09-19.md","ออกแบบ ARCHITECTURE_CDH_2025-09-19.md"] }    หรือส่งแบบ form/query: tasks_csv="งานA,งานB"    """    payload = {}    try:        payload = await req.json()    except Exception:        pass    tasks = []    if isinstance(payload, dict) and "tasks" in payload and isinstance(payload["tasks"], list):        tasks = [str(x).strip() for x in payload["tasks"] if str(x).strip()]    else:        # fallback query/form        qp = dict(req.query_params)        csv = qp.get("tasks_csv") or ""        tasks = [t.strip() for t in csv.split(",") if t.strip()]    if not tasks:        raise HTTPException(status_code=400, detail="no tasks provided")    data = _load_latest()    existing = set(data["tasks"]["next"])    added = []    for t in tasks:        if t not in existing:            data["tasks"]["next"].append(t)            added.append(t)    _save_latest(data)    if added:        _notify_line("เพิ่มงานใหม่: " + ", ".join(added))    return {"ok": True, "added": added, "next_count": len(data['tasks']['next'])}